  1338  // Read a MDL7 file
  1339  void MDLImporter::InternReadFile_3DGS_MDL7() {
  1340      ai_assert(nullptr != pScene);
  1341
  1342      MDL::IntSharedData_MDL7 sharedData;
  1343
  1344      // current cursor position in the file
  1345      BE_NCONST MDL::Header_MDL7 *pcHeader = (BE_NCONST MDL::Header_MDL7 *)this->mBuffer;
  1346      const unsigned char *szCurrent = (const unsigned char *)(pcHeader + 1);
  1347
  1348      AI_SWAP4(pcHeader->version);
  1349      AI_SWAP4(pcHeader->bones_num);
  1350      AI_SWAP4(pcHeader->groups_num);
  1351      AI_SWAP4(pcHeader->data_size);
  1352      AI_SWAP4(pcHeader->entlump_size);
  1353      AI_SWAP4(pcHeader->medlump_size);
  1354      AI_SWAP2(pcHeader->bone_stc_size);
  1355      AI_SWAP2(pcHeader->skin_stc_size);
  1356      AI_SWAP2(pcHeader->colorvalue_stc_size);
  1357      AI_SWAP2(pcHeader->material_stc_size);
  1358      AI_SWAP2(pcHeader->skinpoint_stc_size);
  1359      AI_SWAP2(pcHeader->triangle_stc_size);
  1360      AI_SWAP2(pcHeader->mainvertex_stc_size);
  1361      AI_SWAP2(pcHeader->framevertex_stc_size);
  1362      AI_SWAP2(pcHeader->bonetrans_stc_size);
  1363      AI_SWAP2(pcHeader->frame_stc_size);
  1364
  1365      // validate the header of the file. There are some structure
  1366      // sizes that are expected by the loader to be constant
  1367      this->ValidateHeader_3DGS_MDL7(pcHeader);
  1368
  1369      // load all bones (they are shared by all groups, so
  1370      // we'll need to add them to all groups/meshes later)
  1371      // apcBonesOut is a list of all bones or nullptr if they could not been loaded
  1372      szCurrent += pcHeader->bones_num * pcHeader->bone_stc_size;
  1373      sharedData.apcOutBones = this->LoadBones_3DGS_MDL7();
  1374
  1375      // vector to held all created meshes
  1376      std::vector<aiMesh *> *avOutList;
  1377
  1378      // 3 meshes per group - that should be OK for most models
  1379      avOutList = new std::vector<aiMesh *>[pcHeader->groups_num];
  1380      for (uint32_t i = 0; i < pcHeader->groups_num; ++i)
  1381          avOutList[i].reserve(3);
  1382
  1383      // buffer to held the names of all groups in the file
  1384      const size_t buffersize(AI_MDL7_MAX_GROUPNAMESIZE * pcHeader->groups_num);
  1385      char *aszGroupNameBuffer = new char[buffersize];
  1386
  1387      // read all groups
  1388      for (unsigned int iGroup = 0; iGroup < (unsigned int)pcHeader->groups_num; ++iGroup) {
  1389          MDL::IntGroupInfo_MDL7 groupInfo((BE_NCONST MDL::Group_MDL7 *)szCurrent, iGroup);
  1390          szCurrent = (const unsigned char *)(groupInfo.pcGroup + 1);
  1391
  1392          VALIDATE_FILE_SIZE(szCurrent);
  1393
  1394          AI_SWAP4(groupInfo.pcGroup->groupdata_size);
  1395          AI_SWAP4(groupInfo.pcGroup->numskins);
  1396          AI_SWAP4(groupInfo.pcGroup->num_stpts);
  1397          AI_SWAP4(groupInfo.pcGroup->numtris);
  1398          AI_SWAP4(groupInfo.pcGroup->numverts);
  1399          AI_SWAP4(groupInfo.pcGroup->numframes);
  1400
  1401          if (1 != groupInfo.pcGroup->typ) {
  1402              // Not a triangle-based mesh
  1403              ASSIMP_LOG_WARN("[3DGS MDL7] Not a triangle mesh group. Continuing happily");
  1404          }
  1405
  1406          // store the name of the group
  1407          const unsigned int ofs = iGroup * AI_MDL7_MAX_GROUPNAMESIZE;
  1408          ::memcpy(&aszGroupNameBuffer[ofs],
  1409                  groupInfo.pcGroup->name, AI_MDL7_MAX_GROUPNAMESIZE);
  1410
  1411          // make sure '\0' is at the end
  1412          aszGroupNameBuffer[ofs + AI_MDL7_MAX_GROUPNAMESIZE - 1] = '\0';
  1413
  1414          // read all skins
  1415          sharedData.pcMats.reserve(sharedData.pcMats.size() + groupInfo.pcGroup->numskins);
  1416          sharedData.abNeedMaterials.resize(sharedData.abNeedMaterials.size() +
  1417                                                    groupInfo.pcGroup->numskins,
  1418                  false);
  1419
  1420          for (unsigned int iSkin = 0; iSkin < (unsigned int)groupInfo.pcGroup->numskins; ++iSkin) {
  1421              ParseSkinLump_3DGS_MDL7(szCurrent, &szCurrent, sharedData.pcMats);
  1422          }
  1423          // if we have absolutely no skin loaded we need to generate a default material
  1424          if (sharedData.pcMats.empty()) {
  1425              const int iMode = (int)aiShadingMode_Gouraud;
  1426              sharedData.pcMats.push_back(new aiMaterial());
  1427              aiMaterial *pcHelper = (aiMaterial *)sharedData.pcMats[0];
  1428              pcHelper->AddProperty<int>(&iMode, 1, AI_MATKEY_SHADING_MODEL);
  1429
  1430              aiColor3D clr;
  1431              clr.b = clr.g = clr.r = 0.6f;
  1432              pcHelper->AddProperty<aiColor3D>(&clr, 1, AI_MATKEY_COLOR_DIFFUSE);
  1433              pcHelper->AddProperty<aiColor3D>(&clr, 1, AI_MATKEY_COLOR_SPECULAR);
  1434
  1435              clr.b = clr.g = clr.r = 0.05f;
  1436              pcHelper->AddProperty<aiColor3D>(&clr, 1, AI_MATKEY_COLOR_AMBIENT);
  1437
  1438              aiString szName;
  1439              szName.Set(AI_DEFAULT_MATERIAL_NAME);
  1440              pcHelper->AddProperty(&szName, AI_MATKEY_NAME);
  1441
  1442              sharedData.abNeedMaterials.resize(1, false);
  1443          }
  1444
  1445          // now get a pointer to all texture coords in the group
  1446          groupInfo.pcGroupUVs = (BE_NCONST MDL::TexCoord_MDL7 *)szCurrent;
  1447          for (int i = 0; i < groupInfo.pcGroup->num_stpts; ++i) {
  1448              AI_SWAP4(groupInfo.pcGroupUVs[i].u);
  1449              AI_SWAP4(groupInfo.pcGroupUVs[i].v);
  1450          }
  1451          szCurrent += pcHeader->skinpoint_stc_size * groupInfo.pcGroup->num_stpts;
  1452
  1453          // now get a pointer to all triangle in the group
  1454          groupInfo.pcGroupTris = (Triangle_MDL7 *)szCurrent;
  1455          szCurrent += pcHeader->triangle_stc_size * groupInfo.pcGroup->numtris;
  1456
  1457          // now get a pointer to all vertices in the group
  1458          groupInfo.pcGroupVerts = (BE_NCONST MDL::Vertex_MDL7 *)szCurrent;
  1459          for (int i = 0; i < groupInfo.pcGroup->numverts; ++i) {
  1460              AI_SWAP4(groupInfo.pcGroupVerts[i].x);
  1461              AI_SWAP4(groupInfo.pcGroupVerts[i].y);
  1462              AI_SWAP4(groupInfo.pcGroupVerts[i].z);
  1463
  1464              AI_SWAP2(groupInfo.pcGroupVerts[i].vertindex);
  1465              //We can not swap the normal information now as we don't know which of the two kinds it is
  1466          }
  1467          szCurrent += pcHeader->mainvertex_stc_size * groupInfo.pcGroup->numverts;
  1468          VALIDATE_FILE_SIZE(szCurrent);
  1469
  1470          MDL::IntSplitGroupData_MDL7 splitGroupData(sharedData, avOutList[iGroup]);
  1471          MDL::IntGroupData_MDL7 groupData;
  1472          if (groupInfo.pcGroup->numtris && groupInfo.pcGroup->numverts) {
  1473              // build output vectors
  1474              const unsigned int iNumVertices = groupInfo.pcGroup->numtris * 3;
  1475              groupData.vPositions.resize(iNumVertices);
  1476              groupData.vNormals.resize(iNumVertices);
  1477
  1478              if (sharedData.apcOutBones) groupData.aiBones.resize(iNumVertices, UINT_MAX);
  1479
  1480              // it is also possible that there are 0 UV coordinate sets
  1481              if (groupInfo.pcGroup->num_stpts) {
  1482                  groupData.vTextureCoords1.resize(iNumVertices, aiVector3D());
  1483
  1484                  // check whether the triangle data structure is large enough
  1485                  // to contain a second UV coordinate set
  1486                  if (pcHeader->triangle_stc_size >= AI_MDL7_TRIANGLE_STD_SIZE_TWO_UV) {
  1487                      groupData.vTextureCoords2.resize(iNumVertices, aiVector3D());
  1488                      groupData.bNeed2UV = true;
  1489                  }
  1490              }
  1491              groupData.pcFaces.resize(groupInfo.pcGroup->numtris);
  1492
  1493              // read all faces into the preallocated arrays
  1494              ReadFaces_3DGS_MDL7(groupInfo, groupData);
  1495
  1496              // sort by materials
  1497              SortByMaterials_3DGS_MDL7(groupInfo, groupData,
  1498                      splitGroupData);
  1499
  1500              for (unsigned int qq = 0; qq < sharedData.pcMats.size(); ++qq) {
  1501                  if (!splitGroupData.aiSplit[qq]->empty())
  1502                      sharedData.abNeedMaterials[qq] = true;
  1503              }
  1504          } else
  1505              ASSIMP_LOG_WARN("[3DGS MDL7] Mesh group consists of 0 "
  1506                              "vertices or faces. It will be skipped.");
  1507
  1508          // process all frames and generate output meshes
  1509          ProcessFrames_3DGS_MDL7(groupInfo, groupData, sharedData, szCurrent, &szCurrent);
  1510          GenerateOutputMeshes_3DGS_MDL7(groupData, splitGroupData);
